const edition = globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2013,"grade":"3-4","contest":"Золотое руно","letters":"ABC","count":60,"language":"kk","points":3,"tasksFile":"ZR_1213_KZ_3-4.pdf","answersFile":"reviewed-3-4-vkz.pdf","title":"Pax Germanica. Единство немецкой стихии","sourceFile":"sources/golden-fleece/2013/interactive-3-4-vkz.json","sections":[{"start":1,"title":"Тарих"},{"start":16,"title":"Әдебиет"},{"start":31,"title":"Күнделікті мәдениет"},{"start":46,"title":"Қалалар мен қамалдар"}],"variant":"kz","editionSuffix":"vkz","editionLabel":"На казахском языке","reviewedKey":true}, [{"number":1,"question":"Б.з. І ғасырында рим легиондары мен герман тайпалары арасында Тевтобург орманында шайқас болды. Оның қаншалықты маңызы болды?","choices":["Германдықтардың Галлияға басып кіруіне жол бермеді","Римдіктер Рейннен Эльбаға дейін қоныстанған герман тайпаларын бағындырды","Римдіктердің Германияға тереңдей ене түсуі тоқтатылды"],"answer":2,"title":"Битва в лесу","steps":["Вождь херусков Арминий разбил три римских легиона Вара в 9 году нашей эры.","После этого римляне ещё воевали за Рейном, но приостановили постоянное продвижение вглубь Германии."]},{"number":2,"question":"Аңыз бойынша, бұл құстың атымен Габсбургтер династиясының ата-ба-басынан мұра болып келе жатқан қамалының аты аталған.","choices":["Қаршыға","Сұңқар","Аққу"],"answer":0,"title":"Птица над замком","steps":["Одно из легендарных объяснений названия Габсбург связывает его с немецким Habicht, «ястреб».","По этой версии, название замка означает «ястребиный замок»."]},{"number":3,"question":"Бұл тайпаның атымен қазіргі заманғы Германиядағы жерлердің бірінің аты аталған.","choices":["Свевтер","Тюрингтер","Бургундтар"],"answer":1,"title":"Имя современной земли","steps":["Одну из центральных земель Германии называют Тюрингией. Название сохраняет память о раннесредневековом населении.","Это население составляли тюринги."]},{"number":4,"question":"Алғашқы тәуелсіз герман мемлекеті қандай оқиға нәтижесінде пайда болды деп есептелінеді?","choices":["Батыс Рим империясының күйреуі","Ұлы І Карл империясының бөлінуі","Франк корольдігінің ыдырауы"],"answer":1,"title":"Раздел большой империи","steps":["В 843 году внуки Карла Великого разделили его державу по Верденскому договору.","Восточная часть досталась Людовику Немецкому. Из неё выросло средневековое Германское королевство."]},{"number":5,"question":"Басында герцогтық, кейіннен корольдік атанған Пруссия атауы неден шықты?","choices":["Император Августтың ағасы Прустың атынан","прусстар тайпасынан","Пруссияның бірінші герцогының атынан"],"answer":1,"title":"Откуда имя Пруссии","steps":["У юго-восточного берега Балтики жили древние балтские племена. Позднее их земли завоевал Тевтонский орден.","Название местных пруссов перешло к территории и возникшему на ней государству."]},{"number":6,"question":"Қай ресей патшайымының әкесі прусс фельдмаршалы болған?","choices":["ІІ Екатерина","І Екатерина","Анна Иоанновна"],"answer":0,"title":"Семья императрицы","steps":["София Августа Фредерика происходила из Ангальт-Цербстского дома. Её отец Христиан Август служил в прусской армии.","После перехода в православие она стала Екатериной Алексеевной, будущей Екатериной II."]},{"number":7,"question":"Көп нұсқалардың бірінде айтылғандай, Германия астанасының атауы осы жануармен байланысты екен.","choices":["Құндыз","Аю","Борсық"],"answer":1,"title":"Животное на гербе","steps":["На берлинском гербе изображён чёрный медведь. По-немецки слово «медведь» звучит Bär.","Игра звуков дала народное объяснение названия Берлин. Лингвисты также связывают его со славянским названием болотистой местности."]},{"number":8,"question":"1805жылы Наполеон Ресей мен Австрияның одақтас әскерін қай жерде болған шайқаста жеңді?","choices":["Ульмо","Ватерлоо","Аустерлиц"],"answer":2,"title":"Битва трёх императоров","steps":["В 1805 году Наполеон заставил русско-австрийскую армию оставить удобные позиции и прорвал её центр.","Эта битва под Аустерлицем стала крупнейшей победой Наполеона над Третьей коалицией."]},{"number":9,"question":"«Темір канцлер» атанған мемлекеттік қайраткер кім?","choices":["О.фон Бисмарк","Б.фон Бюлов","К.фон Меттерних"],"answer":0,"title":"Железный канцлер","steps":["Политик руководил объединением германских государств вокруг Пруссии. После объединения он стал первым канцлером империи.","«Железным канцлером» прозвали Отто фон Бисмарка."]},{"number":10,"question":"Елді 99 күн билеген Германия императоры кім?","choices":["ІІ Вильгельм","ІІІ Фридрих","І Вильгельм"],"answer":1,"title":"Короткое правление","steps":["В 1888 году после Вильгельма I трон перешёл к его тяжело больному сыну. Тот умер в том же году.","Этим императором был Фридрих III. Его сменил Вильгельм II."]},{"number":11,"question":"Вестфальск бейбіт келісіміне қол қою ненің аяқталғандығын білдірді?","choices":["Бірінші дүниежүзілік соғыстың","Екінші дүниежүзілік соғыстың","Отыз жылдық соғыстың"],"answer":2,"title":"Мир 1648 года","steps":["Договоры в Мюнстере и Оснабрюке положили конец войне, охватившей германские земли после событий 1618 года.","Война длилась тридцать лет. Поэтому её называют Тридцатилетней."]},{"number":12,"question":"Құрамында Германия, Австро-Венгрия және Италия болған ХІХ ғасырдың аяғында құрылған әскери-саяси бірлестік.","choices":["Антанта","Қасиетті одақ","Үштік одақ"],"answer":2,"title":"Три союзника","steps":["В 1882 году Германия и Австро-Венгрия заключили союз с Италией. Участников было трое.","Договор известен как Тройственный союз."]},{"number":13,"question":"Бірінші дүниежүзілік соғыстың басталуына сылтау болған оқиға.","choices":["Неміс әскерлерінің Ресейге қарсы тұтқиылдан шабуыл жасауы","Эрцгерцог Франц Фердинандтың өлтірілуі","Антантаның ыдырауы"],"answer":1,"title":"Событие в Сараеве","steps":["В июне 1914 года в Сараеве был убит наследник австро-венгерского престола. В ответ Австро-Венгрия предъявила ультиматум Сербии.","Убийство Франца Фердинанда стало непосредственным поводом к войне."]},{"number":14,"question":"Б.з.д. ІІ ғасырда гректердің варвар тайпаларын жеңу құрметіне салынған атақты Пергам алтарін тапқан неміс археологы.","choices":["Г.Шлиман","К.Хуман","В.Дерпфельд"],"answer":1,"title":"Раскопки в Пергаме","steps":["В Пергаме нашли рельефы, где боги сражаются с гигантами. Раскопки конца XIX века велись немецкой экспедицией.","Ею руководил Карл Хуман, который обнаружил Пергамский алтарь."]},{"number":15,"question":"1847 жылы Ресей азаматтығын алған атақты неміс археологы кім?","choices":["Г.Шлиман","К.Хуман","В.Дерпфельд"],"answer":0,"title":"Археолог в России","steps":["Будущий исследователь Трои до раскопок занимался торговлей. Он жил в Петербурге и получил российское подданство.","Это немецкий археолог Генрих Шлиман."]},{"number":16,"question":"Ағайынды Гриммдердің ертегісіндегі бремен музыканттарының саны нешеу?","choices":["Төрт","Бес","Алты"],"answer":0,"title":"Состав музыкантов","steps":["От первого хозяина уходит осёл, а в дороге к нему присоединяются пёс, кот и петух.","Осёл, пёс, кот и петух — четверо."]},{"number":17,"question":"Ағайынды Гриммдердің «Бұрқасын ханшайым» ертегісіндегі өгей қыз күн сайын қандай жұмыс істеуі тиіс еді?","choices":["Үйдің ішін жинау","Таңғы ас дайындау","Тоқыма тоқу"],"answer":2,"title":"Ежедневная работа","steps":["В начале сказки падчерица сидит у колодца с веретеном. Она роняет веретено и прыгает за ним.","Инструмент выдаёт её ежедневное занятие — прядение пряжи."]},{"number":18,"question":"Ағайынды Гриммдердің ертегісінде Дроздобород патша патшайымның алдында қандай кейіпте көрінді?","choices":["Атақты князь","Кедей музыкант","Қарапайым ақсүйек"],"answer":1,"title":"Переодетый король","steps":["Капризную принцессу выдают за бедного человека, который пришёл к дворцу. Он зарабатывает песней и игрой.","Позже выясняется, что музыкантом притворился сам король Дроздобород."]},{"number":19,"question":"Ағайынды Гриммдердің «Үш бақытты жігіт» ертегісіндегі шаруа өз ұлдарына қандай жануарларды мұра етіп қалдырды?","choices":["Жылқы, шошқа","Есек, ит","Әтеш, мысық"],"answer":2,"title":"Скромное наследство","steps":["Отец передаёт троим сыновьям петуха, косу и кошку. Каждый предмет оказывается полезен там, где о нём раньше не знали.","Животных в списке два — петух и кошка."]},{"number":20,"question":"Ағайынды Гриммдердің «Ержүрек тігінші» ертегісінде патша тігіншіге қандай ғажайып жануарды ұстап әкелуді бұйырды?","choices":["Жалғыз мүйізді аң","Айдаһар","Кентавр"],"answer":0,"title":"Поручение портному","steps":["Портной заманивает опасное существо к дереву. Оно бросается на него и застревает рогом в стволе.","Один рог выдаёт единорога."]},{"number":21,"question":"Ағайынды Гриммдердің қай ертегісінде басты кейіпкерлердің бірі наубайханашыдан аяғына қамыр жағып беруді өтінді?","choices":["«Рапунцель»","«Бақа-патша»","«Қасқыр мен жеті лақ»"],"answer":2,"title":"Лапа в тесте","steps":["Козлята не открывают дверь, если видят чёрную лапу. Волк добивается, чтобы его лапа выглядела белой.","Сцена с пекарем есть в сказке «Волк и семеро козлят»."]},{"number":22,"question":"Барон Мюнхгаузеннің айтуынша, басына ағаш өсіп шыққан жануар.","choices":["Бұғы","Қасқыр","Жылқы"],"answer":0,"title":"Дерево на голове","steps":["Барон стреляет в животное вишнёвой косточкой. Позже он снова встречает его и видит, что косточка дала росток.","Вишнёвое дерево якобы выросло на голове оленя."]},{"number":23,"question":"Барон Мюнхгаузеннің айтқан әңгімелерінде ол ми батпақтан қалай шыққан?","choices":["Жіппен","Оны ат алып шыққан","Ол өзін-өзі шашынан тартып алып шыққан"],"answer":2,"title":"Выход из болота","steps":["В обычном мире выбраться без внешней опоры так невозможно. Герой специально рассказывает невероятную историю как правду.","Он уверяет, что вытянул себя и коня за собственные волосы."]},{"number":24,"question":"Неміс ертегілеріндегі қай кейіпкер сиқырлы аяқ киімнің арқасында патшаның жеке желаяғы болды?","choices":["Ләйлек-халиф","Барон Мюнхгаузен","Кішкентай Мук"],"answer":2,"title":"Обувь скорохода","steps":["Волшебные туфли позволяют преодолевать большие расстояния необычайно быстро. Их владелец выигрывает состязание при дворе.","Скороходом делается Маленький Мук."]},{"number":25,"question":"В.Гауфтың «Ләйлек-халиф» ертегісінде ләйлекке айналған халиф пен уәзірге адам кейпіне оралу үшін кім көмектесті?","choices":["Жапалақ","Тасбақа","Кесіртке"],"answer":0,"title":"Помощница в руинах","steps":["Герои забыли волшебное слово и не могут снова стать людьми. Заколдованная принцесса помогает им подслушать это слово.","Принцесса живёт в облике совы."]},{"number":26,"question":"Бұғының баласы Бэмби туралы атақты балалар ертегісін жазған жазушы кім?","choices":["Р.-Э.Распе","Ағайынды Гримм","Ф.Зальтен"],"answer":2,"title":"История оленёнка","steps":["«Бэмби. История жизни в лесу» вышла в 1923 году. Её автор — австрийский писатель и журналист.","Книгу написал Феликс Зальтен. Мультфильм появился позднее."]},{"number":27,"question":"В.Гауфтың ертегісіндегі Тәмпіш мұрын (Кролик нос) қай іспен жетістікке жетті?","choices":["Бағбандық","Аспаздық","Балықшылық"],"answer":1,"title":"Искусство героя","steps":["После превращения герой попадает на службу к герцогу. Он умеет готовить такие блюда, каких придворные прежде не пробовали.","У Карлика Носа особенно хорошо получалась кулинария."]},{"number":28,"question":"Э.Т.А.Гофманның ертегісінде Мари Шақпақшыны (Щелкунчикті) қорғау үшін тышқандарға не лақтырды?","choices":["Кітап","Шырағдан","Аяқ киім"],"answer":2,"title":"Защитница Щелкунчика","steps":["Мыши уже теснят войско игрушек. Мари бросает первое, что может снять с ноги и бросить на расстояние.","Она бросает в мышиного короля туфлю."]},{"number":29,"question":"И.В.Гётенің поэмасында басты кейіпкер болған француз эпосының қаһарманы.","choices":["Роланд","Рейнеке-Лис","Орман патшасы"],"answer":1,"title":"Хитрец из эпоса","steps":["В сказаниях о животных главный герой побеждает противников хитростью. У Гёте он участвует в тяжбах при дворе зверей.","Гёте назвал поэму «Рейнеке-Лис»."]},{"number":30,"question":"Тәмпіш мұрынның (Кролик нос) сиқырының күшін жоятын шөп қандай ағаштың астында өсті?","choices":["Емен","Талшын","Шырша"],"answer":1,"title":"Трава против чар","steps":["Гусыня Мими помогает герою искать особую траву, которой недостаёт для паштета. Её запах разрушает чары.","В сказке траву находят под каштаном."]},{"number":31,"question":"«Фигароның үйлену тойы», «Дон Жуан», «Сиқырлы флейта» операларының авторы, атақты австриялық композитор В.А.Моцарт дүниеге келген қала.","choices":["Зальцбург","Вена","Линц"],"answer":0,"title":"Город Моцарта","steps":["В этом городе на улице Гетрайдегассе сохранился дом семьи композитора. Моцарт родился там в 1756 году.","Дом-музей стоит в Зальцбурге."]},{"number":32,"question":"Швейцариядағы ресми тіл.","choices":["Испан","Ағылшын","Итальян"],"answer":2,"title":"Языки Швейцарии","steps":["Швейцария признаёт немецкий, французский, итальянский и ретороманский национальными языками.","Из предложенных вариантов верен итальянский. На нём говорят, в частности, в кантоне Тичино."]},{"number":33,"question":"Мәскеу мұражайларының бірінде құтырған тон, көзден шыққан ұшқыннан атылатын тапанша және дыбыстар алғашында қатып қалатын, сосын барып еритін мүйіз сияқты жәдігерлер бар. Бұлар қандай әдеби кейіпкерге арналған?","choices":["Шерлок Холмс","Пиноккио","Барон Мюнхгаузен"],"answer":2,"title":"Необычные экспонаты","steps":["Все вещи происходят из рассказов, где невозможный случай подан как обычное приключение. В одном рассказе звуки оживают после оттепели.","Такие истории рассказывал барон Мюнхгаузен."]},{"number":34,"question":"Л.ван Бетховен «Оның аты бұлақ емес, теңіз болу керек еді» деп, кім туралы айтқан?","choices":["В.А.Моцарт","Й.Гайдн","И.С.Бах"],"answer":2,"title":"Ручей или море","steps":["Слово Bach по-немецки означает «ручей». Бетховен обыграл фамилию композитора, считая его музыку гораздо значительнее ручья.","Речь об Иоганне Себастьяне Бахе."]},{"number":35,"question":"Бұл композитор есту қабілетінен толықтай айрылса да, әлемге танымал музыкалық туындыларды өмірге әкелген.","choices":["Ф.Мендельсон","В.А.Моцарт","Л.ван Бетховен"],"answer":2,"title":"Музыка без слуха","steps":["Композитор продолжал работать, хотя постепенно почти полностью оглох. Поздние сонаты и Девятая симфония появились в этот период.","Их написал Людвиг ван Бетховен."]},{"number":36,"question":"Аңызда айтылғандай, рождество шыршасын үйге әкеліп, оны безендіруге ой салған кім?","choices":["Э.Т.А.Гофман","М.Лютер","Я.Гримм"],"answer":1,"title":"Рождественская легенда","steps":["В предании немецкий реформатор увидел свет звёзд среди ветвей и принёс домой дерево со свечами.","Так возникла легенда о рождественской ели Мартина Лютера."]},{"number":37,"question":"Швангау графтарының гербінде қандай құс бейнеленген, сонымен қатар бұл құс Нойшванштайн қамалын көркемдеп безендіруде жетекші мәнге ие.","choices":["Шағала","Бүркіт","Аққу"],"answer":2,"title":"Птица на гербе","steps":["Название Швангау напоминает слово Schwan, «лебедь». Лебедь связан и с легендой о рыцаре Лоэнгрине, которую любил Людвиг II.","Поэтому лебедь повторяется в убранстве Нойшванштайна."]},{"number":38,"question":"Дирижабльдің ерекше үлгісін жасап шығарған неміс ақсүйегі кім? Кейіннен мұндай құрылғыларды соның атымен атайтын болды.","choices":["Ф.Цеппелин","И.Этрих","Х.Юнкерс"],"answer":0,"title":"Дирижабль с каркасом","steps":["Воздушный корабль изобретателя имел прочный каркас и отдельные газовые камеры.","Такие корабли назвали цеппелинами в честь Фердинанда фон Цеппелина."]},{"number":39,"question":"Неміс өнертапқышы И.Гутенберг нені ойлап шығарған?","choices":["Баспа станогын","Бу двигателін","Гидравликалық прессті"],"answer":0,"title":"Изобретение в Майнце","steps":["Изобретатель наладил европейскую печать с помощью отдельного набора подвижных литер. Одним из первых больших изданий стала Библия.","Гутенберг известен именно развитием печатного станка."]},{"number":40,"question":"Ескі атауы «кіші қала» дегенді білдіретін еуропалық қала.","choices":["Люксембург","Гамбург","Аусбург"],"answer":0,"title":"Старинное имя города","steps":["В раннем названии Lucilinburhuc вторая часть означает укрепление, а первая указывает на малые размеры.","От названия небольшой крепости произошло название Люксембурга."]},{"number":41,"question":"Әр жыл сайын 1 қаңтарда дүниежүзі еститін Вена филармониялық оркестрінің «Жаңажылдық концерті» ойналатын зал.","choices":["Күміс зал","Алтын зал","Янтарь зал"],"answer":1,"title":"Зал новогоднего концерта","steps":["Филармоники выступают в здании Венского музыкального общества. Интерьер главного зала обильно украшен позолотой.","Зал называется Золотым."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/41.webp","alt":"Зал новогоднего концерта · 41-тапсырмаға сурет · Сол нысанның басқа фотосуреті","caption":"41-тапсырмаға сурет · Сол нысанның басқа фотосуреті","detailSrc":"assets/golden-fleece/2013/interactive-3-4-kz/41-detail.webp","width":620,"height":413}},{"number":42,"question":"1898 жылы Шайтан көпірдің жанында Альпі тауларының Швейцариядағы бөлігінде ашылған ескерткіш қандай орыс қолбасшысы мен оның әскеріне арналған?","choices":["А.Румянцев","М.Кутузов","А.Суворов"],"answer":2,"title":"Поход через Альпы","steps":["Русское войско пересекло Альпы в 1799 году. Бой у Чёртова моста связан с этим переходом.","Монумент посвящён полководцу Александру Суворову и его войску."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/42.webp","alt":"Поход через Альпы · 42-тапсырмаға сурет","caption":"42-тапсырмаға сурет","width":116,"height":95}},{"number":43,"question":"Вавилонда қазба жұмыстарын жүргізген кезде табылған Иштар қақпасы қай мұражайға қойылған?","choices":["Неміс тарихи мұражайы","Берлин сурет галереясы","Пергам мұражайы"],"answer":2,"title":"Ворота из Вавилона","steps":["На синих глазурованных кирпичах ворот видны рельефы животных. Найденные фрагменты собрали в Берлине.","Ворота Иштар установлены в Пергамском музее."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/43.webp","alt":"Ворота из Вавилона · 43-тапсырмаға сурет","caption":"43-тапсырмаға сурет","width":113,"height":92}},{"number":44,"question":"ХҮІІІ ғасырда Австрияның қай қаласында Мирабель саябағын ергежейлілердің қызықты мүсіндерімен безендірген?","choices":["Зальцбург","Инсбрук","Грац"],"answer":0,"title":"Фигуры в парке","steps":["Дворец и сады Мирабель известны барочными композициями и отдельным садом с фигурами карликов.","Ансамбль Мирабель находится в Зальцбурге."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/44.webp","alt":"Фигуры в парке · 44-тапсырмаға сурет","caption":"44-тапсырмаға сурет","width":115,"height":94}},{"number":45,"question":"Немістің Гиссен қаласында орналасқан бұл мұражайға барсаң, алып сабын көпіршігін көріп, ішіне кіре аласың, айнадағы қиял әлемімен таныса аласың, сондай-ақ барлық жәдігерлерді қолыңмен ұстап көре аласың. Бұл қандай мұражай?","choices":["Ойыншықтар мұражайы","Обергессен мұражайы","Математикум"],"answer":2,"title":"Музей опытов","steps":["Экспонаты устроены как математические опыты: посетитель строит, сравнивает и наблюдает. Мыльная плёнка показывает форму поверхности.","Интерактивный музей Гиссена называется «Математикум»."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/45.webp","alt":"Музей опытов · 45-тапсырмаға сурет","caption":"45-тапсырмаға сурет","width":112,"height":89}},{"number":46,"question":"Еуропа құрлығының қаржы орталығы болып табылатын қала.","choices":["Кёльн","Бремен","Франкфурт-на-Майне"],"answer":2,"title":"Финансовый центр","steps":["В городе расположены биржа и Европейский центральный банк. Его высокие банковские здания узнают на фоне реки Майн.","Это Франкфурт-на-Майне."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/46.webp","alt":"Финансовый центр · 46-тапсырмаға сурет","caption":"46-тапсырмаға сурет","width":123,"height":101}},{"number":47,"question":"1970 жылы М.Шагал інжілдегі оқиғалар желісімен шыныдан құрастырылған 5 сурет салып берген шіркеу қай қалада орналасқан?","choices":["Люксембург","Вена","Цюрих"],"answer":2,"title":"Витражи Шагала","steps":["Пять длинных витражей на библейские сюжеты установлены в хоре церкви Фраумюнстер.","Эта церковь находится в Цюрихе."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/47.webp","alt":"Витражи Шагала · 47-тапсырмаға сурет","caption":"47-тапсырмаға сурет","width":122,"height":98}},{"number":48,"question":"Ұлы неміс композиторы И.С.Бах Әулие Фома шіркеуінде 25 жылдан артық уақыт қандай қалада жұмыс істеді?","choices":["Веймар","Лейпциг","Берлин"],"answer":1,"title":"Кантор церкви","steps":["Бах руководил хором школы Святого Фомы и сочинял музыку для богослужений. Он работал здесь с 1723 года до смерти.","Школа и церковь Святого Фомы находятся в Лейпциге."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/48.webp","alt":"Кантор церкви · 48-тапсырмаға сурет","caption":"48-тапсырмаға сурет","width":121,"height":96}},{"number":49,"question":"Аңызға сәйкес, атауы император Маттиас аңға шыққан кезде тапқан мөлдір суы бар бұлақпен байланысты сарай қайсысы?","choices":["Нимфенбург","Шёнбрунн","Сан-Суси"],"answer":1,"title":"Родник у дворца","steps":["В немецком названии schön означает «красивый», а Brunnen — «источник» или «колодец».","По легенде, имя венского дворца Шёнбрунн связано с таким источником."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/49.webp","alt":"Родник у дворца · 49-тапсырмаға сурет","caption":"49-тапсырмаға сурет","width":121,"height":96}},{"number":50,"question":"Бұл қала ХҮІІІ-ХІХ ғасырлар аралығында неміс Ағарту ісінің орталығы болған, ал ондағы Опера театры алдында И.В.Гёте мен Ф.Шиллерге ескерткіш орнатылған. Бұл қай қала?","choices":["Гамбург","Веймар","Берлин"],"answer":1,"title":"Город поэтов","steps":["Гёте и Шиллер жили и работали при дворе одного небольшого немецкого государства. Их совместный памятник стоит перед Национальным театром.","Памятник находится в Веймаре."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/50.webp","alt":"Город поэтов · 50-тапсырмаға сурет","caption":"50-тапсырмаға сурет","width":120,"height":96}},{"number":51,"question":"Алдында ІІ Фридрихтің жеке резиденциясы болған, ал 1991 жылдан оның жерленген орны болып табылатын сарай.","choices":["Цициленхоф","Сан-Суси","Райнсберг"],"answer":1,"title":"Летняя резиденция","steps":["Фридрих II построил дворец на виноградных террасах в Потсдаме. Французское имя означает «без забот».","Это Сан-Суси, где по его желанию устроили могилу."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/51.webp","alt":"Летняя резиденция · 51-тапсырмаға сурет","caption":"51-тапсырмаға сурет","width":121,"height":96}},{"number":52,"question":"30-дан артық үй орналасқан көше-көпір қай қалада?","choices":["Эрфурт","Гамбург","Франкфурт-на-Майне"],"answer":0,"title":"Мост как улица","steps":["По обе стороны мостовой стоят дома, а посередине проходит улица торговцев. Мост называется Кремербрюке.","Такой мост сохранился в Эрфурте."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/52.webp","alt":"Мост как улица · 52-тапсырмаға сурет","caption":"52-тапсырмаға сурет","width":114,"height":92}},{"number":53,"question":"Қазіргі кезде бұл қамал жыл сайын миллионнан астам саяхатшылар келіп тамашалайтын мұражайға айналған.","choices":["Берг","Левенбург","Нойшванштайн"],"answer":2,"title":"Замок над ущельем","steps":["Замок с белыми стенами и башнями был задуман Людвигом II как романтическая резиденция. Он стоит на горном выступе.","Теперь посетители осматривают его как музей Нойшванштайн."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/53.webp","alt":"Замок над ущельем · 53-тапсырмаға сурет","caption":"53-тапсырмаға сурет","width":125,"height":103}},{"number":54,"question":"Бұл қамалда арнайы механизмнің арқасында ас үйдегі үстел асханаға тамағы жасалған күйінде көтеріліп, түскі асты қызметшілердің көмегінсіз-ақ ішуге мүмкіндік берген. Бұл қандай қамал?","choices":["Херренкимзее","Нойшванштайн","Линдерхоф"],"answer":2,"title":"Стол без слуг","steps":["Механизм поднимал накрытый стол с нижнего этажа прямо в столовую. Король мог обедать один.","Стол такого устройства сохранился в Линдерхофе."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/54.webp","alt":"Стол без слуг · 54-тапсырмаға сурет","caption":"54-тапсырмаға сурет","width":121,"height":97}},{"number":55,"question":"Әлемдегі ең биік готикалық собор қай қалада орналасқан?","choices":["Любек","Ульм","Кёльн"],"answer":1,"title":"Высота собора","steps":["У собора огромная западная башня со шпилем высотой около 161,5 метра. Такой высоты она достигла после достройки в XIX веке.","Это готический собор Ульма."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/55.webp","alt":"Высота собора · 55-тапсырмаға сурет","caption":"55-тапсырмаға сурет","width":121,"height":97}},{"number":56,"question":"Ежелгі римдіктер салған антикалық қақпа осы қаланың басты көрікті орындарының біріне айналған. Бұл қай қала?","choices":["Мюнхен","Трир","Любек"],"answer":1,"title":"Римские ворота","steps":["Два башенных объёма ворот соединены каменными переходами. Тёмный цвет дал памятнику имя Порта-Нигра.","Римские ворота Порта-Нигра находятся в Трире."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/56.webp","alt":"Римские ворота · 56-тапсырмаға сурет","caption":"56-тапсырмаға сурет","width":121,"height":96}},{"number":57,"question":"Германия тарихы мен мәдениетіндегі көрнекті тұлғаларға арналған Атақ Залы – Вальхалла қандай қаладан бірнеше шақырым жерде орналасқан?","choices":["Кёльн","Гамбург","Регенсбург"],"answer":2,"title":"Зал славы над Дунаем","steps":["Вальхалла выглядит как древнегреческий храм. Внутри собраны бюсты выдающихся людей германской истории.","Она стоит у Дуная недалеко от Регенсбурга."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/57.webp","alt":"Зал славы над Дунаем · 57-тапсырмаға сурет","caption":"57-тапсырмаға сурет","width":121,"height":96}},{"number":58,"question":"Қызыл Телпектің, Етік киген мысықтың және Ұйқыдағы арудың суреттерімен безендірілген архитектуралық ансамбль қай қалада?","choices":["Берлин","Зальцбург","Франкфурт-на-Майне"],"answer":0,"title":"Сказки в парке","steps":["В большом фонтанном ансамбле герои сказок выстроены по краям воды. Это Фонтан сказок в Народном парке Фридрихсхайн.","Парк с таким фонтаном находится в Берлине."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/58.webp","alt":"Сказки в парке · 58-тапсырмаға сурет","caption":"58-тапсырмаға сурет","width":121,"height":97}},{"number":59,"question":"Үлкендіктері шын өмірдегі көлеміндей, ақ фарфордан жасалған жануарлар мен құстардың мүсіндерімен безендірілген, барокко стиліндегі архитектуралық ансамбль қай қалада?","choices":["Мюнхен","Берлин","Дрезден"],"answer":2,"title":"Дворец и фарфор","steps":["Саксонский правитель Август Сильный собирал фарфор. Барочные дома дворцового ансамбля теперь хранят часть коллекции.","Этот ансамбль, Цвингер, расположен в Дрездене."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/59.webp","alt":"Дворец и фарфор · 59-тапсырмаға сурет","caption":"59-тапсырмаға сурет","width":121,"height":96}},{"number":60,"question":"Неоготикалық стильдегі ратуша осы қаладағы басты көрікті орындардың бірі болып табылады. Бұл қай қала?","choices":["Кёльн","Бонн","Мюнхен"],"answer":2,"title":"Неоготическая ратуша","steps":["Самая заметная ратуша на Мариенплац имеет высокую фасадную башню и часы с движущимися фигурами.","Это Новая ратуша Мюнхена."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-kz/60.webp","alt":"Неоготическая ратуша · 60-тапсырмаға сурет","caption":"60-тапсырмаға сурет","width":117,"height":93}}]);
